class Gradebook:
    def __init__(self) -> None:
        # Store assignments: {name: {"weight": float, "kind": str}}
        self.assignments = {}
        # Store grades: {student: {assignment: grade}}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on an assignment."""
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """Calculate weighted average for a student, rounding to two decimal places."""
        if student not in self.grades:
            # If student has no grades at all, use default grade 2.0 for all assignments
            total_weight = sum(assignment["weight"] for assignment in self.assignments.values())
            if total_weight == 0:
                return 2.0
            # All assignments count as 2.0
            weighted_sum = sum(2.0 * assignment["weight"] for assignment in self.assignments.values())
            result = weighted_sum / total_weight
            return round(result, 2)

        # Get all assignments for this student
        student_grades = self.grades[student]

        # Separate homework and quiz assignments
        homework_assignments = []
        quiz_assignments = []

        for assignment_name, assignment_info in self.assignments.items():
            if assignment_info["kind"] == "homework":
                homework_assignments.append((assignment_name, assignment_info))
            elif assignment_info["kind"] == "quiz":
                quiz_assignments.append((assignment_name, assignment_info))

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        # Process homework assignments (all count)
        for assignment_name, assignment_info in homework_assignments:
            grade = student_grades.get(assignment_name, 2.0)
            weighted_sum += grade * assignment_info["weight"]
            total_weight += assignment_info["weight"]

        # Process quiz assignments (drop lowest if more than one)
        if quiz_assignments:
            quiz_grades = []
            for assignment_name, assignment_info in quiz_assignments:
                grade = student_grades.get(assignment_name, 2.0)
                quiz_grades.append((grade, assignment_info["weight"]))

            if len(quiz_grades) > 1:
                # Drop the lowest grade
                quiz_grades.sort(key=lambda x: x[0])  # Sort by grade
                quiz_grades = quiz_grades[1:]  # Keep all except the lowest

            # Add remaining quiz grades
            for grade, weight in quiz_grades:
                weighted_sum += grade * weight
                total_weight += weight

        # Handle edge case where total_weight is 0
        if total_weight == 0:
            return 2.0

        result = weighted_sum / total_weight
        return round(result, 2)
